struct Reader<'a>{data:&'a[u8],at:usize}impl<'a>Reader<'a>{fn new(data:&'a[u8])->Self{Self{data,at:0}}fn bytes(&mut self,n:usize)->Result<&'a[u8],ProgramError>{let end=self.at.checked_add(n).ok_or(err(AntError::Arithmetic))?;if end>self.data.len(){return Err(err(AntError::InvalidInstruction));}let out=&self.data[self.at..end];self.at=end;Ok(out)}fn u8(&mut self)->Result<u8,ProgramError>{Ok(self.bytes(1)?[0])}fn u16(&mut self)->Result<u16,ProgramError>{Ok(u16::from_le_bytes(self.bytes(2)?.try_into().unwrap()))}fn u64(&mut self)->Result<u64,ProgramError>{Ok(u64::from_le_bytes(self.bytes(8)?.try_into().unwrap()))}fn i64(&mut self)->Result<i64,ProgramError>{Ok(i64::from_le_bytes(self.bytes(8)?.try_into().unwrap()))}fn a32(&mut self)->Result<[u8;32],ProgramError>{Ok(self.bytes(32)?.try_into().unwrap())}fn done(&self)->ProgramResult{if self.at==self.data.len(){Ok(())}else{Err(err(AntError::InvalidInstruction))}}}
fn signer(a:&AccountInfo)->ProgramResult{if a.is_signer{Ok(())}else{Err(err(AntError::MissingSignature))}}fn writable(a:&AccountInfo)->ProgramResult{if a.is_writable{Ok(())}else{Err(err(AntError::InvalidAccount))}}fn owned(a:&AccountInfo,owner:&Pubkey)->ProgramResult{if a.owner==owner{Ok(())}else{Err(err(AntError::InvalidAccount))}}
fn create_pda<'a>(program_id:&Pubkey,payer:&AccountInfo<'a>,account:&AccountInfo<'a>,system:&AccountInfo<'a>,seeds:&[&[u8]],bump:u8,size:usize)->ProgramResult{if system.key!=&system_program::id(){return Err(err(AntError::InvalidAccount));}if account.owner==program_id{return Err(err(AntError::Replay));}if account.owner!=&system_program::id()||!account.data_is_empty(){return Err(err(AntError::InvalidState));}let rent=Rent::get()?.minimum_balance(size);let bump_seed=[bump];let mut signed=seeds.to_vec();signed.push(&bump_seed);if account.lamports()==0{return invoke_signed(&system_instruction::create_account(payer.key,account.key,rent,size as u64,program_id),&[payer.clone(),account.clone(),system.clone()],&[signed.as_slice()]);}if account.lamports()<rent{invoke(&system_instruction::transfer(payer.key,account.key,rent-account.lamports()),&[payer.clone(),account.clone(),system.clone()])?;}invoke_signed(&system_instruction::allocate(account.key,size as u64),&[account.clone(),system.clone()],&[signed.as_slice()])?;invoke_signed(&system_instruction::assign(account.key,program_id),&[account.clone(),system.clone()],&[signed.as_slice()])}

fn load_config(program_id:&Pubkey,a:&AccountInfo)->Result<Config,ProgramError>{owned(a,program_id)?;let(expected,_)=Pubkey::find_program_address(&[b"config"],program_id);if a.key!=&expected{return Err(err(AntError::InvalidAccount));}let d=a.try_borrow_data()?;if d.len()!=CONFIG_LEN||d[0]!=CONFIG_TAG||d[1]!=1{return Err(err(AntError::InvalidAccount));}Ok(Config{bump:d[2],network:d[5..37].try_into().unwrap(),mint:Pubkey::new_from_array(d[37..69].try_into().unwrap()),administrator:Pubkey::new_from_array(d[69..101].try_into().unwrap()),agent:Pubkey::new_from_array(d[101..133].try_into().unwrap()),settlement_authority:Pubkey::new_from_array(d[133..165].try_into().unwrap()),settlement_mode:d[165],oracle_owner:Pubkey::new_from_array(d[166..198].try_into().unwrap()),oracle_feeds:[d[198..230].try_into().unwrap(),d[230..262].try_into().unwrap()],oracle_max_gap:u64::from_le_bytes(d[262..270].try_into().unwrap()),oracle_max_confidence_bps:u16::from_le_bytes(d[270..272].try_into().unwrap())})}
fn save_config(a:&AccountInfo,c:&Config)->ProgramResult{let mut d=a.try_borrow_mut_data()?;d.fill(0);d[0]=CONFIG_TAG;d[1]=1;d[2]=c.bump;d[3..5].copy_from_slice(&SCHEMA_VERSION.to_le_bytes());d[5..37].copy_from_slice(&c.network);d[37..69].copy_from_slice(c.mint.as_ref());d[69..101].copy_from_slice(c.administrator.as_ref());d[101..133].copy_from_slice(c.agent.as_ref());d[133..165].copy_from_slice(c.settlement_authority.as_ref());d[165]=c.settlement_mode;d[166..198].copy_from_slice(c.oracle_owner.as_ref());d[198..230].copy_from_slice(&c.oracle_feeds[0]);d[230..262].copy_from_slice(&c.oracle_feeds[1]);d[262..270].copy_from_slice(&c.oracle_max_gap.to_le_bytes());d[270..272].copy_from_slice(&c.oracle_max_confidence_bps.to_le_bytes());Ok(())}
fn load_round(program_id:&Pubkey,a:&AccountInfo)->Result<Round,ProgramError>{owned(a,program_id)?;let d=a.try_borrow_data()?;if d.len()!=ROUND_LEN||d[0]!=ROUND_TAG{return Err(err(AntError::InvalidAccount));}let id=u64::from_le_bytes(d[2..10].try_into().unwrap());let(expected,_)=Pubkey::find_program_address(&[b"round",&id.to_le_bytes()],program_id);if a.key!=&expected{return Err(err(AntError::InvalidAccount));}let mut prices=[0i64;4];let mut confidences=[0u64;4];let mut exponents=[0i32;4];let mut publish=[0i64;4];let mut prev=[0i64;4];for i in 0..4{prices[i]=i64::from_le_bytes(d[230+i*8..238+i*8].try_into().unwrap());confidences[i]=u64::from_le_bytes(d[262+i*8..270+i*8].try_into().unwrap());exponents[i]=i32::from_le_bytes(d[294+i*4..298+i*4].try_into().unwrap());publish[i]=i64::from_le_bytes(d[310+i*8..318+i*8].try_into().unwrap());prev[i]=i64::from_le_bytes(d[342+i*8..350+i*8].try_into().unwrap());}Ok(Round{bump:d[1],id,config:Pubkey::new_from_array(d[10..42].try_into().unwrap()),deposit_vault:Pubkey::new_from_array(d[42..74].try_into().unwrap()),forecast_commitment:d[74..106].try_into().unwrap(),entry_open:i64::from_le_bytes(d[106..114].try_into().unwrap()),entry_close:i64::from_le_bytes(d[114..122].try_into().unwrap()),observation_end:i64::from_le_bytes(d[122..130].try_into().unwrap()),settlement_deadline:i64::from_le_bytes(d[130..138].try_into().unwrap()),reveal_end:i64::from_le_bytes(d[138..146].try_into().unwrap()),claim_end:i64::from_le_bytes(d[146..154].try_into().unwrap()),reward_pool:u64::from_le_bytes(d[154..162].try_into().unwrap()),reward_paid:u64::from_le_bytes(d[162..170].try_into().unwrap()),total_deposited:u64::from_le_bytes(d[170..178].try_into().unwrap()),total_correct:[u64::from_le_bytes(d[178..186].try_into().unwrap()),u64::from_le_bytes(d[186..194].try_into().unwrap())],results:[d[194],d[195]],settled_mask:d[196],rolled:d[197]!=0,oracle_evidence:d[198..230].try_into().unwrap(),oracle_prices:prices,oracle_confidences:confidences,oracle_exponents:exponents,oracle_publish_times:publish,oracle_prev_publish_times:prev})}
fn save_round(a:&AccountInfo,r:&Round)->ProgramResult{let mut d=a.try_borrow_mut_data()?;d.fill(0);d[0]=ROUND_TAG;d[1]=r.bump;d[2..10].copy_from_slice(&r.id.to_le_bytes());d[10..42].copy_from_slice(r.config.as_ref());d[42..74].copy_from_slice(r.deposit_vault.as_ref());d[74..106].copy_from_slice(&r.forecast_commitment);d[106..114].copy_from_slice(&r.entry_open.to_le_bytes());d[114..122].copy_from_slice(&r.entry_close.to_le_bytes());d[122..130].copy_from_slice(&r.observation_end.to_le_bytes());d[130..138].copy_from_slice(&r.settlement_deadline.to_le_bytes());d[138..146].copy_from_slice(&r.reveal_end.to_le_bytes());d[146..154].copy_from_slice(&r.claim_end.to_le_bytes());d[154..162].copy_from_slice(&r.reward_pool.to_le_bytes());d[162..170].copy_from_slice(&r.reward_paid.to_le_bytes());d[170..178].copy_from_slice(&r.total_deposited.to_le_bytes());d[178..186].copy_from_slice(&r.total_correct[0].to_le_bytes());d[186..194].copy_from_slice(&r.total_correct[1].to_le_bytes());d[194]=r.results[0];d[195]=r.results[1];d[196]=r.settled_mask;d[197]=r.rolled as u8;d[198..230].copy_from_slice(&r.oracle_evidence);for i in 0..4{d[230+i*8..238+i*8].copy_from_slice(&r.oracle_prices[i].to_le_bytes());d[262+i*8..270+i*8].copy_from_slice(&r.oracle_confidences[i].to_le_bytes());d[294+i*4..298+i*4].copy_from_slice(&r.oracle_exponents[i].to_le_bytes());d[310+i*8..318+i*8].copy_from_slice(&r.oracle_publish_times[i].to_le_bytes());d[342+i*8..350+i*8].copy_from_slice(&r.oracle_prev_publish_times[i].to_le_bytes());}Ok(())}
fn load_capsule(program_id:&Pubkey,a:&AccountInfo)->Result<Capsule,ProgramError>{owned(a,program_id)?;let d=a.try_borrow_data()?;if d.len()!=CAPSULE_LEN||d[0]!=CAPSULE_TAG{return Err(err(AntError::InvalidAccount));}let round_id=u64::from_le_bytes(d[2..10].try_into().unwrap());let wallet=Pubkey::new_from_array(d[10..42].try_into().unwrap());let(expected,_)=Pubkey::find_program_address(&[b"capsule",&round_id.to_le_bytes(),wallet.as_ref()],program_id);if a.key!=&expected{return Err(err(AntError::InvalidAccount));}Ok(Capsule{bump:d[1],round_id,wallet,commitment:d[42..74].try_into().unwrap(),ciphertext_hash:d[74..106].try_into().unwrap(),deposit:u64::from_le_bytes(d[106..114].try_into().unwrap()),ciphertext_len:u16::from_le_bytes(d[114..116].try_into().unwrap()),ciphertext:d[116..628].try_into().unwrap(),revealed:d[628]!=0,answers:[d[629],d[630]],withdrawn:d[631]!=0,claimed:d[632]!=0,reward_paid:u64::from_le_bytes(d[633..641].try_into().unwrap())})}
fn save_capsule(a:&AccountInfo,c:&Capsule)->ProgramResult{let mut d=a.try_borrow_mut_data()?;d.fill(0);d[0]=CAPSULE_TAG;d[1]=c.bump;d[2..10].copy_from_slice(&c.round_id.to_le_bytes());d[10..42].copy_from_slice(c.wallet.as_ref());d[42..74].copy_from_slice(&c.commitment);d[74..106].copy_from_slice(&c.ciphertext_hash);d[106..114].copy_from_slice(&c.deposit.to_le_bytes());d[114..116].copy_from_slice(&c.ciphertext_len.to_le_bytes());d[116..628].copy_from_slice(&c.ciphertext);d[628]=c.revealed as u8;d[629]=c.answers[0];d[630]=c.answers[1];d[631]=c.withdrawn as u8;d[632]=c.claimed as u8;d[633..641].copy_from_slice(&c.reward_paid.to_le_bytes());Ok(())}
fn token_account(a:&AccountInfo,token_program:&Pubkey)->Result<(Pubkey,Pubkey,u64),ProgramError>{if a.owner!=token_program{return Err(err(AntError::InvalidToken));}let d=a.try_borrow_data()?;if d.len()!=165||d[108]!=1||u32::from_le_bytes(d[72..76].try_into().unwrap())!=0||u32::from_le_bytes(d[129..133].try_into().unwrap())!=0{return Err(err(AntError::InvalidToken));}Ok((Pubkey::new_from_array(d[0..32].try_into().unwrap()),Pubkey::new_from_array(d[32..64].try_into().unwrap()),u64::from_le_bytes(d[64..72].try_into().unwrap())))}
fn mint_decimals(a:&AccountInfo,token_program:&Pubkey)->Result<u8,ProgramError>{if a.owner!=token_program{return Err(err(AntError::InvalidToken));}let d=a.try_borrow_data()?;if d.len()!=82||d[45]!=1||u32::from_le_bytes(d[0..4].try_into().unwrap())!=0||u32::from_le_bytes(d[46..50].try_into().unwrap())!=0{return Err(err(AntError::InvalidToken));}Ok(d[44])}
fn token_transfer_checked<'a>(source:&AccountInfo<'a>,mint:&AccountInfo<'a>,dest:&AccountInfo<'a>,authority:&AccountInfo<'a>,token:&AccountInfo<'a>,amount:u64,decimals:u8,seeds:Option<&[&[u8]]>)->ProgramResult{let mut data=Vec::with_capacity(10);data.push(12);data.extend_from_slice(&amount.to_le_bytes());data.push(decimals);let ix=solana_program::instruction::Instruction{program_id:*token.key,accounts:vec![solana_program::instruction::AccountMeta::new(*source.key,false),solana_program::instruction::AccountMeta::new_readonly(*mint.key,false),solana_program::instruction::AccountMeta::new(*dest.key,false),solana_program::instruction::AccountMeta::new_readonly(*authority.key,true)],data};let infos=[source.clone(),mint.clone(),dest.clone(),authority.clone(),token.clone()];match seeds{Some(s)=>invoke_signed(&ix,&infos,&[s]),None=>invoke(&ix,&infos)}}

pub fn process_instruction(program_id:&Pubkey,accounts:&[AccountInfo],data:&[u8])->ProgramResult{let mut rd=Reader::new(data);let op=rd.u8()?;let minimum=match op{0=>4,1=>7,2=>3,3=>9,4=>3,5=>1,6=>3,7=>9,8=>3,9=>2,10=>6,_=>return Err(err(AntError::InvalidInstruction))};if accounts.len()<minimum{return Err(ProgramError::NotEnoughAccountKeys);}match op{0=>initialize(program_id,accounts,&mut rd),1=>create_round(program_id,accounts,&mut rd),2=>fund(program_id,accounts,&mut rd),3=>enter(program_id,accounts,&mut rd),4=>settle_local(program_id,accounts,&mut rd),5=>cancel_timeout(program_id,accounts,&mut rd),6=>reveal(program_id,accounts,&mut rd),7=>withdraw(program_id,accounts,&mut rd),8=>claim(program_id,accounts,&mut rd),9=>rollover(program_id,accounts,&mut rd),10=>settle_pyth(program_id,accounts,&mut rd),_=>unreachable!()}}
fn valid_oracle_config(owner:Pubkey,feeds:[[u8;32];2],max_gap:u64,max_confidence_bps:u16)->bool{owner!=Pubkey::default()&&feeds[0]!=[0;32]&&feeds[1]!=[0;32]&&feeds[0]!=feeds[1]&&max_gap>0&&max_confidence_bps>0&&max_confidence_bps<=1000}
fn initialize(program_id:&Pubkey,accounts:&[AccountInfo],rd:&mut Reader)->ProgramResult{let mut it=accounts.iter();let admin=next_account_info(&mut it)?;let config_a=next_account_info(&mut it)?;let system=next_account_info(&mut it)?;let program=next_account_info(&mut it)?;signer(admin)?;writable(config_a)?;let network=rd.a32()?;let mint=Pubkey::new_from_array(rd.a32()?);let agent=Pubkey::new_from_array(rd.a32()?);let settlement=Pubkey::new_from_array(rd.a32()?);let mode=rd.u8()?;let(oracle_owner,oracle_feeds,oracle_max_gap,oracle_max_confidence_bps)=if mode==2{(Pubkey::new_from_array(rd.a32()?),[rd.a32()?,rd.a32()?],rd.u64()?,rd.u16()?)}else{(Pubkey::default(),[[0;32];2],0,0)};rd.done()?;if mode>2||mint==Pubkey::default()||agent==Pubkey::default()||program.key!=program_id||!program.executable{return Err(err(AntError::InvalidInstruction));}if mode==2&&!valid_oracle_config(oracle_owner,oracle_feeds,oracle_max_gap,oracle_max_confidence_bps){return Err(err(AntError::InvalidInstruction));}if mode==1{if program.owner!=&bpf_loader::id(){return Err(err(AntError::WrongAuthority));}}else{if program.owner!=&bpf_loader_upgradeable::id(){return Err(err(AntError::WrongAuthority));}let programdata=next_account_info(&mut it)?;let pd_key={let d=program.try_borrow_data()?;if d.len()!=36||u32::from_le_bytes(d[0..4].try_into().unwrap())!=2{return Err(err(AntError::InvalidAccount));}Pubkey::new_from_array(d[4..36].try_into().unwrap())};if programdata.key!=&pd_key||programdata.owner!=&bpf_loader_upgradeable::id(){return Err(err(AntError::InvalidAccount));}let d=programdata.try_borrow_data()?;if d.len()<45||u32::from_le_bytes(d[0..4].try_into().unwrap())!=3||d[12]!=1||Pubkey::new_from_array(d[13..45].try_into().unwrap())!=*admin.key{return Err(err(AntError::WrongAuthority));}}let(expected,bump)=Pubkey::find_program_address(&[b"config"],program_id);if config_a.key!=&expected{return Err(err(AntError::InvalidAccount));}create_pda(program_id,admin,config_a,system,&[b"config"],bump,CONFIG_LEN)?;save_config(config_a,&Config{bump,network,mint,administrator:*admin.key,agent,settlement_authority:settlement,settlement_mode:mode,oracle_owner,oracle_feeds,oracle_max_gap,oracle_max_confidence_bps})}
fn create_round(program_id:&Pubkey,accounts:&[AccountInfo],rd:&mut Reader)->ProgramResult{let mut it=accounts.iter();let admin=next_account_info(&mut it)?;let agent=next_account_info(&mut it)?;let config_a=next_account_info(&mut it)?;let round_a=next_account_info(&mut it)?;let vault=next_account_info(&mut it)?;let token=next_account_info(&mut it)?;let system=next_account_info(&mut it)?;signer(admin)?;signer(agent)?;writable(round_a)?;let c=load_config(program_id,config_a)?;if admin.key!=&c.administrator||agent.key!=&c.agent{return Err(err(AntError::WrongAuthority));}if token.key!=&TOKEN_PROGRAM{return Err(err(AntError::InvalidToken));}let id=rd.u64()?;let entry_open=rd.i64()?;let entry_close=rd.i64()?;let observation_end=rd.i64()?;let settlement_deadline=rd.i64()?;let reveal_end=rd.i64()?;let claim_end=rd.i64()?;let forecast=rd.a32()?;rd.done()?;let now=Clock::get()?.unix_timestamp;if !(now<entry_open&&entry_open<entry_close&&entry_close<observation_end&&observation_end<settlement_deadline&&settlement_deadline<reveal_end&&reveal_end<claim_end)||forecast==[0;32]{return Err(err(AntError::Deadline));}let idb=id.to_le_bytes();let(expected,bump)=Pubkey::find_program_address(&[b"round",&idb],program_id);if round_a.key!=&expected{return Err(err(AntError::InvalidAccount));}let(va,_)=Pubkey::find_program_address(&[b"vault-authority",&idb],program_id);let(vm,vo,_)=token_account(vault,token.key)?;if vm!=c.mint||vo!=va{return Err(err(AntError::InvalidToken));}create_pda(program_id,admin,round_a,system,&[b"round",&idb],bump,ROUND_LEN)?;save_round(round_a,&Round{bump,id,config:*config_a.key,deposit_vault:*vault.key,forecast_commitment:forecast,entry_open,entry_close,observation_end,settlement_deadline,reveal_end,claim_end,reward_pool:0,reward_paid:0,total_deposited:0,total_correct:[0,0],results:[CANCELED_BUCKET;2],settled_mask:0,rolled:false,oracle_evidence:[0;32],oracle_prices:[0;4],oracle_confidences:[0;4],oracle_exponents:[0;4],oracle_publish_times:[0;4],oracle_prev_publish_times:[0;4]})}
fn fund(program_id:&Pubkey,accounts:&[AccountInfo],rd:&mut Reader)->ProgramResult{let mut it=accounts.iter();let funder=next_account_info(&mut it)?;let round_a=next_account_info(&mut it)?;let system=next_account_info(&mut it)?;signer(funder)?;writable(round_a)?;let amount=rd.u64()?;rd.done()?;if amount==0{return Err(err(AntError::InvalidInstruction));}let mut r=load_round(program_id,round_a)?;if Clock::get()?.unix_timestamp>=r.entry_open{return Err(err(AntError::Deadline));}r.reward_pool=r.reward_pool.checked_add(amount).ok_or(err(AntError::Arithmetic))?;invoke(&system_instruction::transfer(funder.key,round_a.key,amount),&[funder.clone(),round_a.clone(),system.clone()])?;save_round(round_a,&r)}
fn enter(program_id:&Pubkey,accounts:&[AccountInfo],rd:&mut Reader)->ProgramResult{let mut it=accounts.iter();let wallet=next_account_info(&mut it)?;let config_a=next_account_info(&mut it)?;let round_a=next_account_info(&mut it)?;let capsule_a=next_account_info(&mut it)?;let source=next_account_info(&mut it)?;let vault=next_account_info(&mut it)?;let mint=next_account_info(&mut it)?;let token=next_account_info(&mut it)?;let system=next_account_info(&mut it)?;signer(wallet)?;writable(round_a)?;writable(capsule_a)?;if token.key!=&TOKEN_PROGRAM{return Err(err(AntError::InvalidToken));}let c=load_config(program_id,config_a)?;let mut r=load_round(program_id,round_a)?;if r.config!=*config_a.key||r.deposit_vault!=*vault.key||mint.key!=&c.mint{return Err(err(AntError::InvalidAccount));}let now=Clock::get()?.unix_timestamp;if now<r.entry_open||now>=r.entry_close{return Err(err(AntError::Deadline));}let deposit=rd.u64()?;let commitment=rd.a32()?;let ciphertext_hash=rd.a32()?;let len=rd.u16()? as usize;if deposit==0||len==0||len>MAX_CIPHERTEXT{return Err(err(AntError::InvalidInstruction));}let cipher=rd.bytes(len)?;rd.done()?;if hashv(&[cipher]).to_bytes()!=ciphertext_hash{return Err(err(AntError::InvalidCommitment));}let idb=r.id.to_le_bytes();let(expected,bump)=Pubkey::find_program_address(&[b"capsule",&idb,wallet.key.as_ref()],program_id);if capsule_a.key!=&expected{return Err(err(AntError::InvalidAccount));}let(va,_)=Pubkey::find_program_address(&[b"vault-authority",&idb],program_id);let(sm,so,sa)=token_account(source,token.key)?;let(vm,vo,_)=token_account(vault,token.key)?;if sm!=c.mint||so!=*wallet.key||sa<deposit||vm!=c.mint||vo!=va{return Err(err(AntError::InvalidToken));}let decimals=mint_decimals(mint,token.key)?;create_pda(program_id,wallet,capsule_a,system,&[b"capsule",&idb,wallet.key.as_ref()],bump,CAPSULE_LEN)?;token_transfer_checked(source,mint,vault,wallet,token,deposit,decimals,None)?;r.total_deposited=r.total_deposited.checked_add(deposit).ok_or(err(AntError::Arithmetic))?;let mut ciphertext=[0u8;MAX_CIPHERTEXT];ciphertext[..len].copy_from_slice(cipher);save_round(round_a,&r)?;save_capsule(capsule_a,&Capsule{bump,round_id:r.id,wallet:*wallet.key,commitment,ciphertext_hash,deposit,ciphertext_len:len as u16,ciphertext,revealed:false,answers:[CANCELED_BUCKET;2],withdrawn:false,claimed:false,reward_paid:0})}
#[derive(Clone,Copy)]struct PythPrice{price:i64,conf:u64,exponent:i32,publish_time:i64,prev_publish_time:i64}
fn pyth_price_data(d:&[u8],feed:&[u8;32],target:i64,max_gap:u64,max_confidence_bps:u16)->Result<PythPrice,ProgramError>{if d.len()<133||d[0..8]!=PYTH_PRICE_UPDATE_V2_DISCRIMINATOR||d[40]!=1{return Err(err(AntError::InvalidAccount));}let at=41;if &d[at..at+32]!=feed{return Err(err(AntError::InvalidAccount));}let p=PythPrice{price:i64::from_le_bytes(d[at+32..at+40].try_into().unwrap()),conf:u64::from_le_bytes(d[at+40..at+48].try_into().unwrap()),exponent:i32::from_le_bytes(d[at+48..at+52].try_into().unwrap()),publish_time:i64::from_le_bytes(d[at+52..at+60].try_into().unwrap()),prev_publish_time:i64::from_le_bytes(d[at+60..at+68].try_into().unwrap())};if p.price<=0||p.exponent < -18||p.exponent>18||p.prev_publish_time>=target||target>p.publish_time{return Err(err(AntError::InvalidState));}let gap=i64::try_from(max_gap).map_err(|_|err(AntError::Arithmetic))?;if p.publish_time.checked_sub(p.prev_publish_time).ok_or(err(AntError::Arithmetic))?>gap||p.publish_time.checked_sub(target).ok_or(err(AntError::Arithmetic))?>gap{return Err(err(AntError::Deadline));}if (p.conf as u128).checked_mul(10_000).ok_or(err(AntError::Arithmetic))?>(p.price as u128).checked_mul(max_confidence_bps as u128).ok_or(err(AntError::Arithmetic))?{return Err(err(AntError::InvalidState));}Ok(p)}
fn pyth_price(a:&AccountInfo,owner:&Pubkey,feed:&[u8;32],target:i64,max_gap:u64,max_confidence_bps:u16)->Result<PythPrice,ProgramError>{if a.owner!=owner{return Err(err(AntError::InvalidAccount));}let d=a.try_borrow_data()?;pyth_price_data(&d,feed,target,max_gap,max_confidence_bps)}
fn return_bucket(base:i64,end:i64)->Result<u8,ProgramError>{if base<=0||end<=0{return Err(err(AntError::InvalidState));}let scaled=(end as i128-base as i128).checked_mul(100).ok_or(err(AntError::Arithmetic))?;let boundary=(base as i128).checked_mul(5).ok_or(err(AntError::Arithmetic))?;Ok(if scaled < -boundary{0}else if scaled<0{1}else if scaled<boundary{2}else{3})}
fn settle_pyth(program_id:&Pubkey,accounts:&[AccountInfo],rd:&mut Reader)->ProgramResult{rd.done()?;let config_a=&accounts[0];let round_a=&accounts[1];writable(round_a)?;let c=load_config(program_id,config_a)?;if c.settlement_mode!=2{return Err(err(AntError::ProductionSettlementDisabled));}let mut r=load_round(program_id,round_a)?;if r.config!=*config_a.key||r.settled_mask==3{return Err(err(AntError::Replay));}let now=Clock::get()?.unix_timestamp;if now<r.observation_end||now>=r.settlement_deadline{return Err(err(AntError::Deadline));}let mut accepted=0u8;for q in 0..2{let bit=1u8<<q;if r.settled_mask&bit!=0{continue;}let base_i=q*2;let base=pyth_price(&accounts[2+base_i],&c.oracle_owner,&c.oracle_feeds[q],r.entry_close,c.oracle_max_gap,c.oracle_max_confidence_bps);let end=pyth_price(&accounts[3+base_i],&c.oracle_owner,&c.oracle_feeds[q],r.observation_end,c.oracle_max_gap,c.oracle_max_confidence_bps);if let(Ok(base),Ok(end))=(base,end){if base.exponent!=end.exponent{continue;}r.results[q]=return_bucket(base.price,end.price)?;let prices=[base,end];let mut identities=[[0u8;32];2];for j in 0..2{let i=base_i+j;let d=accounts[2+i].try_borrow_data()?;identities[j]=hashv(&[accounts[2+i].key.as_ref(),&d]).to_bytes();r.oracle_prices[i]=prices[j].price;r.oracle_confidences[i]=prices[j].conf;r.oracle_exponents[i]=prices[j].exponent;r.oracle_publish_times[i]=prices[j].publish_time;r.oracle_prev_publish_times[i]=prices[j].prev_publish_time;}let qb=[q as u8];r.oracle_evidence=hashv(&[&r.oracle_evidence,&qb,&identities[0],&identities[1]]).to_bytes();r.settled_mask|=bit;accepted|=bit;}}if accepted==0{return Err(err(AntError::InvalidAccount));}save_round(round_a,&r)}
fn settle_local(program_id:&Pubkey,accounts:&[AccountInfo],rd:&mut Reader)->ProgramResult{let mut it=accounts.iter();let authority=next_account_info(&mut it)?;let config_a=next_account_info(&mut it)?;let round_a=next_account_info(&mut it)?;signer(authority)?;writable(round_a)?;let results=[rd.u8()?,rd.u8()?];rd.done()?;let c=load_config(program_id,config_a)?;if c.settlement_mode!=1{return Err(err(AntError::ProductionSettlementDisabled));}if authority.key!=&c.settlement_authority{return Err(err(AntError::WrongAuthority));}if results.iter().any(|v|*v>3){return Err(err(AntError::InvalidInstruction));}let mut r=load_round(program_id,round_a)?;if r.config!=*config_a.key{return Err(err(AntError::InvalidAccount));}let now=Clock::get()?.unix_timestamp;if now<r.observation_end||now>=r.settlement_deadline{return Err(err(AntError::Deadline));}if r.settled_mask!=0{return Err(err(AntError::Replay));}r.results=results;r.settled_mask=3;save_round(round_a,&r)}
fn cancel_timeout(program_id:&Pubkey,accounts:&[AccountInfo],rd:&mut Reader)->ProgramResult{rd.done()?;let round_a=&accounts[0];writable(round_a)?;let mut r=load_round(program_id,round_a)?;if Clock::get()?.unix_timestamp<r.settlement_deadline{return Err(err(AntError::Deadline));}if r.settled_mask==3{return Err(err(AntError::Replay));}for i in 0..2{let bit=1u8<<i;if r.settled_mask&bit==0{r.results[i]=CANCELED_BUCKET;r.settled_mask|=bit;}}save_round(round_a,&r)}
fn reveal(program_id:&Pubkey,accounts:&[AccountInfo],rd:&mut Reader)->ProgramResult{let config_a=&accounts[0];let round_a=&accounts[1];let capsule_a=&accounts[2];writable(round_a)?;writable(capsule_a)?;let c=load_config(program_id,config_a)?;let mut r=load_round(program_id,round_a)?;let mut cap=load_capsule(program_id,capsule_a)?;if r.config!=*config_a.key||cap.round_id!=r.id{return Err(err(AntError::InvalidAccount));}let schema=rd.u16()?;let answers=[rd.u8()?,rd.u8()?];let salt=rd.a32()?;rd.done()?;if schema!=SCHEMA_VERSION||answers.iter().any(|v|*v>3){return Err(err(AntError::InvalidInstruction));}let now=Clock::get()?.unix_timestamp;if now<r.observation_end||now>=r.reveal_end||r.settled_mask!=3{return Err(err(AntError::Deadline));}if cap.revealed{return Err(err(AntError::Replay));}let idb=r.id.to_le_bytes();let sb=schema.to_le_bytes();let expected=hashv(&[DOMAIN,program_id.as_ref(),&c.network,c.mint.as_ref(),&idb,cap.wallet.as_ref(),&sb,&answers,&salt]).to_bytes();if expected!=cap.commitment{return Err(err(AntError::InvalidCommitment));}for i in 0..2{if r.results[i]!=CANCELED_BUCKET&&answers[i]==r.results[i]{r.total_correct[i]=r.total_correct[i].checked_add(cap.deposit).ok_or(err(AntError::Arithmetic))?;}}cap.revealed=true;cap.answers=answers;save_round(round_a,&r)?;save_capsule(capsule_a,&cap)}
fn withdraw(program_id:&Pubkey,accounts:&[AccountInfo],rd:&mut Reader)->ProgramResult{rd.done()?;let mut it=accounts.iter();let wallet=next_account_info(&mut it)?;let config_a=next_account_info(&mut it)?;let round_a=next_account_info(&mut it)?;let capsule_a=next_account_info(&mut it)?;let vault=next_account_info(&mut it)?;let destination=next_account_info(&mut it)?;let mint=next_account_info(&mut it)?;let vault_authority=next_account_info(&mut it)?;let token=next_account_info(&mut it)?;signer(wallet)?;writable(capsule_a)?;let c=load_config(program_id,config_a)?;let r=load_round(program_id,round_a)?;let mut cap=load_capsule(program_id,capsule_a)?;if r.config!=*config_a.key{return Err(err(AntError::InvalidAccount));}if Clock::get()?.unix_timestamp<r.observation_end{return Err(err(AntError::Deadline));}if cap.wallet!=*wallet.key||cap.round_id!=r.id{return Err(err(AntError::WrongAuthority));}if cap.withdrawn{return Err(err(AntError::Replay));}if vault.key!=&r.deposit_vault||mint.key!=&c.mint||token.key!=&TOKEN_PROGRAM{return Err(err(AntError::InvalidToken));}let idb=r.id.to_le_bytes();let(va,bump)=Pubkey::find_program_address(&[b"vault-authority",&idb],program_id);if vault_authority.key!=&va{return Err(err(AntError::InvalidAccount));}let(dm,do_,_)=token_account(destination,token.key)?;if dm!=c.mint||do_!=*wallet.key{return Err(err(AntError::InvalidToken));}let decimals=mint_decimals(mint,token.key)?;let bs=[bump];let seeds:[&[u8];3]=[b"vault-authority",&idb,&bs];token_transfer_checked(vault,mint,destination,vault_authority,token,cap.deposit,decimals,Some(&seeds))?;cap.withdrawn=true;save_capsule(capsule_a,&cap)}
fn claim(program_id:&Pubkey,accounts:&[AccountInfo],rd:&mut Reader)->ProgramResult{rd.done()?;let wallet=&accounts[0];let round_a=&accounts[1];let capsule_a=&accounts[2];signer(wallet)?;writable(round_a)?;writable(capsule_a)?;writable(wallet)?;let mut r=load_round(program_id,round_a)?;let mut cap=load_capsule(program_id,capsule_a)?;let now=Clock::get()?.unix_timestamp;if now<r.reveal_end||now>=r.claim_end{return Err(err(AntError::Deadline));}if cap.wallet!=*wallet.key||cap.round_id!=r.id{return Err(err(AntError::WrongAuthority));}if !cap.revealed{return Err(err(AntError::InvalidState));}if cap.claimed{return Err(err(AntError::Replay));}let question_pool=r.reward_pool/2;let mut reward=0u64;for i in 0..2{if r.results[i]!=CANCELED_BUCKET&&cap.answers[i]==r.results[i]&&r.total_correct[i]>0{let share=(question_pool as u128).checked_mul(cap.deposit as u128).ok_or(err(AntError::Arithmetic))?/(r.total_correct[i] as u128);reward=reward.checked_add(u64::try_from(share).map_err(|_|err(AntError::Arithmetic))?).ok_or(err(AntError::Arithmetic))?;}}r.reward_paid=r.reward_paid.checked_add(reward).ok_or(err(AntError::Arithmetic))?;if r.reward_paid>r.reward_pool{return Err(err(AntError::Arithmetic));}if reward>0{let from=round_a.lamports().checked_sub(reward).ok_or(err(AntError::Arithmetic))?;let to=wallet.lamports().checked_add(reward).ok_or(err(AntError::Arithmetic))?;**round_a.try_borrow_mut_lamports()?=from;**wallet.try_borrow_mut_lamports()?=to;}cap.claimed=true;cap.reward_paid=reward;save_round(round_a,&r)?;save_capsule(capsule_a,&cap)}
fn rollover(program_id:&Pubkey,accounts:&[AccountInfo],rd:&mut Reader)->ProgramResult{rd.done()?;let source_a=&accounts[0];let target_a=&accounts[1];writable(source_a)?;writable(target_a)?;let mut source=load_round(program_id,source_a)?;let mut target=load_round(program_id,target_a)?;let now=Clock::get()?.unix_timestamp;if now<source.claim_end||now>=target.entry_open{return Err(err(AntError::Deadline));}if source.rolled||source.config!=target.config{return Err(err(AntError::Replay));}let amount=source.reward_pool.checked_sub(source.reward_paid).ok_or(err(AntError::Arithmetic))?;target.reward_pool=target.reward_pool.checked_add(amount).ok_or(err(AntError::Arithmetic))?;source.rolled=true;if amount>0{let from=source_a.lamports().checked_sub(amount).ok_or(err(AntError::Arithmetic))?;let to=target_a.lamports().checked_add(amount).ok_or(err(AntError::Arithmetic))?;**source_a.try_borrow_mut_lamports()?=from;**target_a.try_borrow_mut_lamports()?=to;}save_round(source_a,&source)?;save_round(target_a,&target)}

#[cfg(test)]mod tests{use super::*;fn update(feed:[u8;32],price:i64,conf:u64,publish:i64,prev:i64)->[u8;133]{let mut d=[0u8;133];d[0..8].copy_from_slice(&PYTH_PRICE_UPDATE_V2_DISCRIMINATOR);d[40]=1;d[41..73].copy_from_slice(&feed);d[73..81].copy_from_slice(&price.to_le_bytes());d[81..89].copy_from_slice(&conf.to_le_bytes());d[89..93].copy_from_slice(&(-8i32).to_le_bytes());d[93..101].copy_from_slice(&publish.to_le_bytes());d[101..109].copy_from_slice(&prev.to_le_bytes());d}#[test]fn layout_sizes_are_stable(){assert_eq!(CONFIG_LEN,272);assert_eq!(ROUND_LEN,374);assert_eq!(CAPSULE_LEN,642);}#[test]fn bucket_math_is_exact(){let pool=101u128;assert_eq!(pool*2/3,67);assert_eq!(return_bucket(10_000,9_499).unwrap(),0);assert_eq!(return_bucket(10_000,9_500).unwrap(),1);assert_eq!(return_bucket(10_000,10_499).unwrap(),2);assert_eq!(return_bucket(10_000,10_500).unwrap(),3);}#[test]fn pyth_decoder_requires_full_feed_boundary_gap_and_confidence(){let feed=[7u8;32];let d=update(feed,20_000_000_000,10_000,105,99);assert_eq!(pyth_price_data(&d,&feed,100,10,100).unwrap().price,20_000_000_000);let mut partial=d;partial[40]=0;assert!(pyth_price_data(&partial,&feed,100,10,100).is_err());assert!(pyth_price_data(&d,&[8u8;32],100,10,100).is_err());assert!(pyth_price_data(&d,&feed,99,10,100).is_err());assert!(pyth_price_data(&d,&feed,100,5,100).is_err());let wide=update(feed,20_000_000_000,300_000_000,105,99);assert!(pyth_price_data(&wide,&feed,100,10,100).is_err());}#[test]fn oracle_config_rejects_identical_question_feeds(){let owner=Pubkey::new_unique();assert!(valid_oracle_config(owner,[[7u8;32],[8u8;32]],30,100));assert!(!valid_oracle_config(owner,[[7u8;32],[7u8;32]],30,100));}}
